func (s *Service) verifyRegistrationTurnstile(ctx context.Context, cfg config.Config, tokenValue string, remoteIP string) error {
	if !cfg.TurnstileRegistrationEnabled {
		return nil
	}
	siteKey := strings.TrimSpace(cfg.TurnstileSiteKey)
	if siteKey == "" {
		return nil
	}
	secretKey := strings.TrimSpace(cfg.TurnstileSecretKey)
	if secretKey == "" {
		return errTurnstileNotConfigured
	}

	token := strings.TrimSpace(tokenValue)
	if token == "" {
		return errTurnstileRequired
	}
	if len(token) > turnstileTokenMaxLength {
		return errTurnstileTokenTooLong
	}

	form := url.Values{}
	form.Set("secret", secretKey)
	form.Set("response", token)
	if ip := strings.TrimSpace(remoteIP); ip != "" {
		form.Set("remoteip", ip)
	}

	endpoint := strings.TrimSpace(cfg.TurnstileSiteverifyURL)
	if endpoint == "" {
		endpoint = config.DefaultTurnstileSiteverifyURL
	}
	response, err := s.providerHTTPClient.PostForm(
		ctx,
		endpoint,
		[]string{endpoint},
		form,
		map[string]string{"Accept": "application/json"},
	)
	if err != nil {
		s.warn("turnstile siteverify request failed: " + err.Error())
		return errTurnstileFailed
	}
	var result turnstileSiteverifyResponse
	if err = json.Unmarshal(response.Body, &result); err != nil {
		s.warn(fmt.Sprintf("turnstile siteverify decode failed: status=%d error=%v", response.StatusCode, err))
		return errTurnstileFailed
	}
	if !response.Successful() || !result.Success {
		s.warn(fmt.Sprintf("turnstile siteverify rejected: status=%d error_codes=%s", response.StatusCode, strings.Join(result.ErrorCodes, ",")))
		return errTurnstileFailed
	}
	return nil
}
func RateLimit(limiter RateLimiter, runtime *config.Runtime) gin.HandlerFunc {
	return func(c *gin.Context) {
		if limiter == nil || !rateLimitEnabled(runtime) {
			c.Next()
			return
		}

		userID, exists := c.Get(ContextKeyUserID)
		if !exists {
			c.Next()
			return
		}
		role, hasRole := c.Get(ContextKeyUserRole)
		if roleStr, ok := role.(string); hasRole && ok && domainuser.IsAdminRole(roleStr) {
			c.Next()
			return
		}

		policy := authenticatedRateLimitPolicy(c, authenticatedRateLimitRPM(runtime))
		key := fmt.Sprintf("ratelimit:user:%v:%s", userID, policy.Name)
		allowed, err := limiter.AllowSlidingWindow(c.Request.Context(), key, policy.Limit, policy.Window, policy.TTL)
		if err != nil || allowed {
			c.Next()
			return
		}
		writeRateLimitError(c, policy)
	}
}

// PublicAuthRateLimit 淇濇姢鍏紑鎺ュ彛锛屾寜 IP銆佹帴鍙ｄ笌椋庨櫓绛夌骇闄愭祦銆?
func PublicAuthRateLimit(limiter RateLimiter, runtime *config.Runtime) gin.HandlerFunc {
	return func(c *gin.Context) {
		if limiter == nil || !rateLimitEnabled(runtime) {
			c.Next()
			return
		}

		clientIP := c.ClientIP()
		if clientIP == "" {
			clientIP = "unknown"
		}

		policy := publicRateLimitPolicy(c, publicAuthRateLimitRPM(runtime))
		key := fmt.Sprintf("ratelimit:public:%s:%s:ip:%s", policy.Name, normalizedRoutePath(c), clientIP)
		if policy.Name == "auth_refresh" {
			key = fmt.Sprintf("ratelimit:token-refresh:ip:%s", clientIP)
		}

		allowed, err := limiter.AllowFixedWindow(c.Request.Context(), []string{key}, policy.Limit, policy.TTL)
		if err != nil || allowed {
			c.Next()
			return
		}
		writeRateLimitError(c, policy)
	}
}

